//! Copies the MIME table generated by Nix into `OUT_DIR`.
//!
//! The crate GENERATES nothing: what generates is `nix/scripts/gen-mimedb.py`,
//! because the checks that matter — a generic icon nobody answers for, a token
//! that does not exist — have to take the SYSTEM's build down and not just this
//! crate's.

use std::path::PathBuf;

fn main() {
    let dir = std::env::var("RONOCTUA_MIME_DIR").expect(
        "RONOCTUA_MIME_DIR is not set.\n\
         \n\
         It comes out of `nix/mimegen.nix`. Compiling this crate outside the devshell or\n\
         crane does not work, and should not: the table is generated by Nix out of\n\
         the pinned `shared-mime-info`.",
    );
    let out = PathBuf::from(std::env::var("OUT_DIR").expect("OUT_DIR"));
    let origin = PathBuf::from(&dir).join("mimedb.rs");

    // READ, DELETE and WRITE — not `fs::copy`. The store is read-only and
    // `fs::copy` preserves the mode, so the SECOND compilation fails with
    // `Permission denied` while overwriting a file it wrote itself. The same
    // trap `crates/ronoctua-i18n/build.rs` records.
    let content = std::fs::read(&origin)
        .unwrap_or_else(|e| panic!("could not read {}: {e}", origin.display()));
    let destination = out.join("mimedb.rs");
    let _ = std::fs::remove_file(&destination);
    std::fs::write(&destination, content)
        .unwrap_or_else(|e| panic!("could not write {}: {e}", destination.display()));
    println!("cargo::rerun-if-env-changed=RONOCTUA_MIME_DIR");
    println!("cargo::rerun-if-changed={dir}");
    // AND THE CACHE POLICY, for `ronoctua-empty-trash` beside this crate.
    //
    // The same shape and the same trap: `assets/cache.nix` is the one place the
    // numbers live, `nix/cache.nix` turns them into Rust, and generating here
    // would leave that source of truth (invariant 5). The destination is
    // deleted first for the reason written above — the store is read-only and
    // the mode comes with the content.
    println!("cargo:rerun-if-env-changed=RONOCTUA_CACHE_RS");
    let policy = std::env::var("RONOCTUA_CACHE_RS").expect(
        "RONOCTUA_CACHE_RS is not set.\n\
         \n\
         The cache policy is generated by Nix out of `assets/cache.nix`. Enter the\n\
         environment with `direnv allow` (or `nix develop`), or build through the flake.",
    );
    println!("cargo:rerun-if-changed={policy}");
    let cache = out.join("cache.rs");
    let body = std::fs::read(&policy).unwrap_or_else(|e| panic!("could not read {policy}: {e}"));
    let _ = std::fs::remove_file(&cache);
    std::fs::write(&cache, body)
        .unwrap_or_else(|e| panic!("could not write {}: {e}", cache.display()));
}
